import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.ChIlRNAd.js";const y=JSON.parse('{"title":"API Privacy — way out of archive encryption","description":"","frontmatter":{},"headers":[],"relativePath":"en/technical/api/privacy.md","filePath":"en/technical/api/privacy.md"}'),n={name:"en/technical/api/privacy.md"};function r(o,a,p,h,c,l){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="api-privacy-—-way-out-of-archive-encryption" tabindex="-1">API Privacy — way out of archive encryption <a class="header-anchor" href="#api-privacy-—-way-out-of-archive-encryption" aria-label="Permalink to &quot;API Privacy — way out of archive encryption&quot;">​</a></h1><h2 id="prefix-api-privacy" tabindex="-1">Prefix: <code>/api/privacy</code> <a class="header-anchor" href="#prefix-api-privacy" aria-label="Permalink to &quot;Prefix: `/api/privacy`&quot;">​</a></h2><p>Session only (refused to API tokens).</p><p><strong>Archive encryption was removed</strong> from Nid: it only protected the EML files&#39; content (subject, sender, recipients, snippet and attachment names stayed in clear in PostgreSQL), and it made the mail unreadable in Nid, invisible to full-text search, and impossible to restore or share. To protect archives at rest, encrypt the NAS volume (LUKS, encrypted ZFS dataset…): it covers the database too. Only the way out remains: putting already encrypted archives back in clear.</p><hr><h3 id="get-accountid-encryption-status" tabindex="-1"><code>GET /:accountId/encryption/status</code> <a class="header-anchor" href="#get-accountid-encryption-status" aria-label="Permalink to &quot;`GET /:accountId/encryption/status`&quot;">​</a></h3><p>How many archives of the account are still encrypted.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;encrypted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;unencrypted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;percentage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="post-accountid-encryption-decrypt-all" tabindex="-1"><code>POST /:accountId/encryption/decrypt-all</code> <a class="header-anchor" href="#post-accountid-encryption-decrypt-all" aria-label="Permalink to &quot;`POST /:accountId/encryption/decrypt-all`&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;passphrase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-passphrase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Checks the passphrase (<code>403</code> otherwise), then starts a <code>decrypt_archives</code> job (<strong>202</strong> <code>{ &quot;jobId&quot; }</code>) that decrypts every EML and its attachments in place, marks the archive readable, then refills the full-text bodies (<code>backfill_body_text</code>) for search. A wrong passphrase writes nothing (GCM tag). The passphrase is neither stored in the <code>jobs</code> table nor kept in Redis after the job. Rate limit: 5/min. UI: Settings › Data › <strong>Encrypted archives</strong> (shown only when some remain).</p><hr><h2 id="encrypted-file-format" tabindex="-1">Encrypted file format <a class="header-anchor" href="#encrypted-file-format" aria-label="Permalink to &quot;Encrypted file format&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GMENC01 (7 magic bytes) | SALT (32 bytes) | IV (12 bytes) | TAG (16 bytes) | CIPHERTEXT</span></span></code></pre></div><ul><li>Algorithm: AES-256-GCM</li><li>Key derivation: PBKDF2 (SHA-512, 100,000 iterations)</li><li>The passphrase is never stored, only a scrypt hash is kept for verification</li></ul>',15)])])}const k=e(n,[["render",r]]);export{y as __pageData,k as default};
